darwin.lab_tree:
{
  var P = {"label": "从共同祖先分叉而出的生命之树", "leafColors": ["#3B5BDB", "#2F9E44", "#E8590C", "#6741D9", "#0C8599", "#C2255C"]};

  var cv=$("canvas",lab); var sD=$('[data-ctrl="depth"]',lab);
  var out=$(".lab-readout",lab); var vSpan=sD?sD.closest(".ctrl").querySelector(".v"):null;
  var W=820,H=360;
  function draw(){
    var depth=sD?parseInt(sD.value):4;
    var S=setupCanvas(cv,H/W); var ctx=S.ctx,k=S.w/W;
    ctx.save(); ctx.scale(k,k); ctx.clearRect(0,0,W,H); ctx.fillStyle="#FBFCFE"; ctx.fillRect(0,0,W,H);
    ctx.fillStyle="#5C6B82"; ctx.font="600 13px -apple-system,sans-serif"; ctx.fillText(P.label,24,30);
    var colors=P.leafColors||["#3B5BDB","#2F9E44","#E8590C","#6741D9","#0C8599","#C2255C"];
    // 递归画分支
    function branch(x,y,len,ang,d,wd){
      if(d<=0){
        ctx.fillStyle=colors[(d+depth)%colors.length];
        ctx.beginPath(); ctx.arc(x,y,5,0,Math.PI*2); ctx.fill(); return;
      }
      var x2=x+Math.cos(ang)*len, y2=y+Math.sin(ang)*len;
      ctx.strokeStyle="rgba(91,107,130,"+(0.35+0.5*(1-d/depth))+")"; ctx.lineWidth=wd;
      ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(x2,y2); ctx.stroke();
      branch(x2,y2,len*0.72,ang-0.32,d-1,Math.max(1,wd*0.7));
      branch(x2,y2,len*0.72,ang+0.32,d-1,Math.max(1,wd*0.7));
    }
    branch(W/2,H-30,110,-Math.PI/2,depth,8);
    ctx.restore();
    if(vSpan)vSpan.textContent=depth+" 级";
    var tips=Math.pow(2,depth);
    if(out)out.innerHTML="从一根主干开始，每演化一级就一分为二：<b>"+depth+"</b> 级后会出现约 <b>"+tips+"</b> 个末梢——这就是“生命之树”的几何。";
  }
  if(sD)sD.addEventListener("input",draw);
  draw();

}

einstein.labTime:
{
    var cv = $("canvas", lab);
    var sSpeed = $('[data-ctrl="speed"]', lab);
    var out = $(".lab-readout", lab);
    var vSpan = sSpeed ? sSpeed.closest(".ctrl").querySelector(".v") : null;
    var W = 820, H = 360;
    var L = 120;                 // 镜子间距（逻辑像素）
    var cV = 230;                // 光子视觉速度 px/s
    var tick = 0, dir = 1, yPh = -L / 2;
    var shipX = 80, earthT = 0, last = 0;

    function gamma(vf) { var x = 1 - vf * vf; return x > 0 ? 1 / Math.sqrt(x) : 99; }

    function draw(ts) {
      if (!last) last = ts;
      var dt = Math.min(0.05, (ts - last) / 1000); last = ts;
      var vf = sSpeed ? parseFloat(sSpeed.value) : 0;
      var g = gamma(vf);
      yPh += dir * cV * dt;
      if (yPh > L / 2) { yPh = L / 2; dir = -1; tick++; }
      if (yPh < -L / 2) { yPh = -L / 2; dir = 1; tick++; }
      earthT += dt;
      shipX += vf * cV * dt;
      if (shipX > W - 90) shipX = 90;

      var S = setupCanvas(cv, H / W);
      var ctx = S.ctx, k = S.w / W;
      ctx.save(); ctx.scale(k, k);
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = "#FBFCFE"; ctx.fillRect(0, 0, W, H);

      var cx = shipX, cyc = 180;
      ctx.strokeStyle = "#3B5BDB"; ctx.lineWidth = 3;
      ctx.strokeRect(cx - 46, cyc - L / 2 - 20, 92, L + 40);
      ctx.strokeStyle = "#9AA7BE"; ctx.lineWidth = 4;
      ctx.beginPath(); ctx.moveTo(cx - 40, cyc - L / 2); ctx.lineTo(cx + 40, cyc - L / 2); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(cx - 40, cyc + L / 2); ctx.lineTo(cx + 40, cyc + L / 2); ctx.stroke();
      ctx.fillStyle = "#F59F00";
      ctx.beginPath(); ctx.arc(cx, cyc + yPh, 7, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = "rgba(245,159,0,.45)"; ctx.lineWidth = 2; ctx.setLineDash([5, 4]);
      ctx.beginPath(); ctx.moveTo(cx, cyc - L / 2); ctx.lineTo(cx, cyc + L / 2); ctx.stroke(); ctx.setLineDash([]);

      ctx.fillStyle = "#8B96AA"; ctx.font = "600 13px -apple-system, sans-serif";
      ctx.fillText("飞船上的光钟：光在两面镜子间一上一下 = 1 秒", 24, 30);
      ctx.fillStyle = "#1B2530"; ctx.font = "800 20px -apple-system, sans-serif";
      ctx.fillText("γ = " + g.toFixed(2), W - 170, 38);
      ctx.restore();

      if (vSpan) vSpan.textContent = vf.toFixed(2) + " c";
      if (out) {
        out.innerHTML = "飞船速度 " + vf.toFixed(2) + " c　·　γ = " + g.toFixed(2) +
          "　·　飞船钟跳了 <b>" + tick + "</b> 下时，地球已过了 <b>" + earthT.toFixed(1) + "</b> 秒" +
          "（飞船 1 秒 ≈ 地球 " + g.toFixed(2) + " 秒）";
      }
      requestAnimationFrame(draw);
    }
    if (sSpeed) sSpeed.addEventListener("input", function () { tick = 0; earthT = 0; });
    requestAnimationFrame(draw);
  }

einstein.labPhoton:
{
    var cv = $("canvas", lab);
    var sFreq = $('[data-ctrl="freq"]', lab);
    var out = $(".lab-readout", lab);
    var vSpan = sFreq ? sFreq.closest(".ctrl").querySelector(".v") : null;
    var W = 820, H = 300;
    var h_eVs = 4.136e-15;       // 普朗克常数 eV·s
    var Wf = 2.0;                // 逸出功 eV
    var plateX = 210;
    var electrons = [];
    var last = 0, emitAcc = 0;

    function eV(f14) { return h_eVs * f14 * 1e14; }

    function draw(ts) {
      if (!last) last = ts;
      var dt = Math.min(0.05, (ts - last) / 1000); last = ts;
      var f14 = sFreq ? parseFloat(sFreq.value) : 7.0;
      var E = eV(f14);
      var above = E > Wf;
      var KE = above ? E - Wf : 0;

      if (above) {
        emitAcc += dt;
        var rate = 0.07;
        while (emitAcc > rate) {
          emitAcc -= rate;
          electrons.push({ x: plateX + 10, y: 150 + (Math.random() * 50 - 25), vx: 120 + Math.sqrt(KE) * 70 });
        }
      }
      for (var i = electrons.length - 1; i >= 0; i--) {
        electrons[i].x += electrons[i].vx * dt;
        if (electrons[i].x > W - 20) electrons.splice(i, 1);
      }

      var S = setupCanvas(cv, H / W);
      var ctx = S.ctx, k = S.w / W;
      ctx.save(); ctx.scale(k, k); ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = "#FBFCFE"; ctx.fillRect(0, 0, W, H);

      ctx.strokeStyle = "#3B5BDB"; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(20, 150); ctx.lineTo(plateX, 150); ctx.stroke();
      ctx.fillStyle = "#3B5BDB"; ctx.font = "600 12px -apple-system, sans-serif";
      ctx.fillText("光子 h·f（频率越高，单个光子能量越大）", 24, 138);
      ctx.fillStyle = "#EDEFF4"; ctx.strokeStyle = "#8B96AA"; ctx.lineWidth = 2;
      ctx.fillRect(plateX, 90, 16, 120); ctx.strokeRect(plateX, 90, 16, 120);
      ctx.fillStyle = "#0CA678";
      electrons.forEach(function (e) { ctx.beginPath(); ctx.arc(e.x, e.y, 6, 0, Math.PI * 2); ctx.fill(); });
      ctx.strokeStyle = "#E8590C"; ctx.setLineDash([5, 4]); ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(W - 120, 90); ctx.lineTo(W - 120, 210); ctx.stroke(); ctx.setLineDash([]);
      ctx.fillStyle = "#E8590C"; ctx.font = "600 12px -apple-system, sans-serif";
      ctx.fillText("截止电压", W - 162, 80);

      ctx.fillStyle = above ? "#087F5B" : "#E8590C"; ctx.font = "700 13px -apple-system, sans-serif";
      ctx.fillText(above ? "✅ 光子能量够大 → 打出电子" : "❌ 光子能量不足 → 一个电子都打不出", 24, 258);
      ctx.restore();

      if (vSpan) vSpan.textContent = f14.toFixed(1) + " THz";
      if (out) {
        out.innerHTML = "频率 f = " + f14.toFixed(1) + " THz　·　光子能量 = " + E.toFixed(2) + " eV" +
          "　·　截止 " + (Wf / h_eVs / 1e14).toFixed(2) + " THz　·　电子动能 = <b>" + KE.toFixed(2) + " eV</b>" +
          "　·　" + (above ? "打出电子" : "打不出");
      }
      requestAnimationFrame(draw);
    }
    requestAnimationFrame(draw);
  }

einstein.labBend:
{
    var cv = $("canvas", lab);
    var sMass = $('[data-ctrl="mass"]', lab);
    var out = $(".lab-readout", lab);
    var vSpan = sMass ? sMass.closest(".ctrl").querySelector(".v") : null;
    var W = 820, H = 360;
    var cx = 410, cy = 180;
    var path = [];
    var dotT = 0, last = 0;

    function computePath(mass) {
      path = [];
      var x = -20, y = 72, vx = 260, vy = 0;
      var k = 1500 * mass;
      var dt = 0.016;
      for (var i = 0; i < 420; i++) {
        var dx = cx - x, dy = cy - y, r2 = dx * dx + dy * dy;
        var r = Math.sqrt(r2) + 1e-3;
        var a = k / r2;
        vx += a * (dx / r) * dt * 60;
        vy += a * (dy / r) * dt * 60;
        x += vx * dt; y += vy * dt;
        path.push({ x: x, y: y });
        if (x > W + 20) break;
      }
    }

    function draw(ts) {
      if (!last) last = ts;
      var dt = Math.min(0.05, (ts - last) / 1000); last = ts;
      var mass = sMass ? parseFloat(sMass.value) : 10;
      computePath(mass);

      var S = setupCanvas(cv, H / W);
      var ctx = S.ctx, k = S.w / W;
      ctx.save(); ctx.scale(k, k); ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = "#FBFCFE"; ctx.fillRect(0, 0, W, H);

      ctx.fillStyle = "#3B5BDB";
      ctx.beginPath(); ctx.arc(cx, cy, 26, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = "#fff"; ctx.font = "700 12px -apple-system, sans-serif";
      ctx.fillText("恒星", cx - 14, cy + 4);

      ctx.strokeStyle = "#E8590C"; ctx.lineWidth = 3; ctx.beginPath();
      path.forEach(function (p, i) { if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y); });
      ctx.stroke();

      dotT += dt * 0.22; if (dotT > 1) dotT = 0;
      var idx = Math.floor(dotT * (path.length - 1));
      var p = path[idx];
      if (p) { ctx.fillStyle = "#F59F00"; ctx.beginPath(); ctx.arc(p.x, p.y, 7, 0, Math.PI * 2); ctx.fill(); }

      ctx.fillStyle = "#8B96AA"; ctx.font = "600 13px -apple-system, sans-serif";
      ctx.fillText("光本应走直线，却被恒星弯曲的时空“掰”向它", 24, 30);
      ctx.restore();

      if (vSpan) vSpan.textContent = mass.toFixed(0) + " M☉";
      if (out) {
        out.innerHTML = "恒星质量 = " + mass.toFixed(0) + " 倍太阳　·　质量越大，时空弯得越狠，光线偏折越明显" +
          (mass >= 30 ? "（就像 1919 日食里被掰弯的星光）" : "");
      }
      requestAnimationFrame(draw);
    }
    requestAnimationFrame(draw);
  }

faraday.lab_induction:
{
  var P = {"label": "磁铁一动，线圈里就冒出电流"};

  var cv=$("canvas",lab); var sS=$('[data-ctrl="speed"]',lab); var sN=$('[data-ctrl="turns"]',lab);
  var out=$(".lab-readout",lab);
  function _vs(el){ return el?el.closest(".ctrl").querySelector(".v"):null; }
  var vS=_vs(sS), vN=_vs(sN);
  var W=820,H=360, ph=0, last=0, hist=[];
  var CX=430, CY=148;
  function draw(ts){
    if(typeof ts!=="number")ts=Date.now();
    if(!last)last=ts; var dt=Math.min(0.05,(ts-last)/1000); last=ts;
    var sp=sS?parseFloat(sS.value):1;
    var N=sN?parseFloat(sN.value):4;
    var w=sp*1.15; ph+=dt*w;
    var mx=CX+175*Math.sin(ph);
    var vx=175*w*Math.cos(ph);
    var coup=Math.exp(-Math.pow((mx-CX)/115,2));
    var emf=Math.max(-1,Math.min(1, N*vx*coup/250));
    hist.push(emf); if(hist.length>300)hist.shift();
    var S=setupCanvas(cv,H/W); var ctx=S.ctx,k=S.w/W;
    ctx.save(); ctx.scale(k,k); ctx.clearRect(0,0,W,H);
    ctx.fillStyle="#FBFCFE"; ctx.fillRect(0,0,W,H);
    var turns=Math.round(N), i;
    ctx.strokeStyle="#495057"; ctx.lineWidth=2;
    for(i=0;i<turns;i++){
      var ex=CX-46+(turns>1?(92/(turns-1))*i:0);
      ctx.beginPath(); ctx.ellipse(ex,CY,10,62,0,0,Math.PI*2); ctx.stroke();
    }
    ctx.strokeStyle="#868E96"; ctx.lineWidth=1.6;
    ctx.beginPath(); ctx.moveTo(CX+46,CY+62); ctx.lineTo(690,CY+62); ctx.lineTo(690,232); ctx.stroke();
    var mw=118, mh=46;
    ctx.fillStyle="#E03131"; ctx.fillRect(mx-mw/2,CY-mh/2,mw/2,mh);
    ctx.fillStyle="#1C7ED6"; ctx.fillRect(mx,CY-mh/2,mw/2,mh);
    ctx.strokeStyle="#343A40"; ctx.lineWidth=1.4; ctx.strokeRect(mx-mw/2,CY-mh/2,mw,mh);
    ctx.fillStyle="#fff"; ctx.font="700 17px -apple-system,sans-serif"; ctx.textAlign="center";
    ctx.fillText("N",mx-mw/4,CY+6); ctx.fillText("S",mx+mw/4,CY+6);
    ctx.textAlign="left";
    ctx.fillStyle="#FFD43B"; ctx.font="700 12px -apple-system,sans-serif";
    ctx.fillText("磁铁",mx-mw/2,CY-32);
    var gx=690, gy=286, gr=52;
    ctx.fillStyle="#fff"; ctx.strokeStyle="#343A40"; ctx.lineWidth=2;
    ctx.beginPath(); ctx.arc(gx,gy,gr,0,Math.PI*2); ctx.fill(); ctx.stroke();
    ctx.strokeStyle="#ADB5BD"; ctx.lineWidth=1.2;
    for(i=-4;i<=4;i++){
      var aa=-Math.PI/2+i*(Math.PI/2)/4;
      ctx.beginPath(); ctx.moveTo(gx+Math.cos(aa)*(gr-8),gy+Math.sin(aa)*(gr-8));
      ctx.lineTo(gx+Math.cos(aa)*(gr-3),gy+Math.sin(aa)*(gr-3)); ctx.stroke();
    }
    var na=-Math.PI/2+emf*1.05;
    ctx.strokeStyle="#E03131"; ctx.lineWidth=3;
    ctx.beginPath(); ctx.moveTo(gx,gy); ctx.lineTo(gx+Math.cos(na)*(gr-14),gy+Math.sin(na)*(gr-14)); ctx.stroke();
    ctx.fillStyle="#343A40"; ctx.beginPath(); ctx.arc(gx,gy,4,0,Math.PI*2); ctx.fill();
    ctx.fillStyle="#868E96"; ctx.font="600 11px -apple-system,sans-serif"; ctx.textAlign="center";
    ctx.fillText("电流计",gx,gy+gr-10); ctx.textAlign="left";
    var bx=60, by=300, bw=520, bh=44;
    ctx.strokeStyle="#DEE2E6"; ctx.lineWidth=1; ctx.beginPath();
    ctx.moveTo(bx,by+bh/2); ctx.lineTo(bx+bw,by+bh/2); ctx.stroke();
    ctx.strokeStyle="#1C7ED6"; ctx.lineWidth=2; ctx.beginPath();
    for(i=0;i<hist.length;i++){
      var xx=bx+bw*i/300, yy=by+bh/2-hist[i]*(bh/2-4);
      if(i===0)ctx.moveTo(xx,yy); else ctx.lineTo(xx,yy);
    }
    ctx.stroke();
    ctx.fillStyle="#495057"; ctx.font="600 12px -apple-system,sans-serif";
    ctx.fillText("感应电流随时间（磁铁来回穿过线圈）",bx,by-6);
    ctx.fillStyle="#868E96"; ctx.font="600 13px -apple-system,sans-serif";
    ctx.fillText(P.label||"磁铁一动，线圈里就冒出电流", 14, 24);
    ctx.restore();
    if(vS)vS.textContent=sp.toFixed(1)+"×";
    if(vN)vN.textContent=turns+" 匝";
    if(out)out.innerHTML="磁铁速度 <b>"+sp.toFixed(1)+"×</b>、线圈 <b>"+turns+"</b> 匝：此刻感应电流 <b>"+emf.toFixed(2)+"</b>。磁通变化越快、匝数越多，电流越大——这就是法拉第电磁感应定律。";
    requestAnimationFrame(draw);
  }
  if(sS)sS.addEventListener("input",draw);
  if(sN)sN.addEventListener("input",draw);
  requestAnimationFrame(draw);

}

