pasteur.lab_heat:
{
  var P = {"expr": "exp", "label": "加热越强，微生物存活率越低"};

  var cv=$("canvas",lab); var s1=$('[data-ctrl="param1"]',lab); var s2=$('[data-ctrl="param2"]',lab);
